mapper.select:
select pr.id , pr.type, pr.create_time,
p.id 'project.id', p.name 'project.name', p.short_name 'project.shortName', p.serial_number 'project.serialNumber',
u.name operator
from contract_project_record as pr, Contract_project as p, sys_user as u
where pr.project_id = p.id and pr.operation_user_id = u.id
and p.bool_delete_enum = 0 and pr.bool_delete_enum = 0 and u.bool_delete_enum = 0
and u.name like concat('%',#{operator},'%')
and p.id = #{projectId}
and pr.type = #{type}
and pr.create_time >= #{startDate}
and pr.create_time < #{endDate}
